import{c as e,Q as o,j as a,m as i}from"./chunks/framework.W-g_WCNV.js";const p=JSON.parse('{"title":"Social login","description":"Let users sign in with GitHub, Google, or Discord.","frontmatter":{"title":"Social login","description":"Let users sign in with GitHub, Google, or Discord."},"headers":[],"relativePath":"admin/social-login.md","filePath":"admin/social-login.md"}'),r={name:"admin/social-login.md"};function n(s,t,l,d,c,h){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="social-login" tabindex="-1">Social login <a class="header-anchor" href="#social-login" aria-label="Permalink to &quot;Social login&quot;">​</a></h1><p>GateKeeper supports OAuth2 sign-in via GitHub, Google, and Discord. When a provider is enabled, a <strong>Continue with ...</strong> button appears on the login page. Users can also link or unlink providers from their profile page.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>The user clicks a social login button.</li><li>GateKeeper redirects to the provider&#39;s authorization page.</li><li>After the user approves, the provider redirects back to GateKeeper with an authorization code.</li><li>GateKeeper exchanges the code for an access token and fetches the user&#39;s profile.</li><li>GateKeeper looks up the provider identity in its database: <ul><li><strong>Found</strong> - logs in as the linked user.</li><li><strong>Not found, email matches existing user</strong> - links the provider to that account and logs in.</li><li><strong>Not found, no match</strong> - creates a new account (if registration is open) or shows an error.</li></ul></li></ol><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Go to <strong>Admin</strong> &gt; <strong>Settings</strong> &gt; <strong>Social login</strong>.</p><p>For each provider you want to enable:</p><ol><li>Create an OAuth2 application on the provider&#39;s developer console (see below).</li><li>Enter the <strong>Client ID</strong> and <strong>Client secret</strong> in the Settings page.</li><li>Check <strong>Enable</strong> and save.</li></ol><h3 id="callback-url" tabindex="-1">Callback URL <a class="header-anchor" href="#callback-url" aria-label="Permalink to &quot;Callback URL&quot;">​</a></h3><p>Set the redirect / callback URL in the provider&#39;s developer console to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-gatekeeper-domain/auth/social/{provider}/callback</span></span></code></pre></div><p>Replace <code>{provider}</code> with <code>github</code>, <code>google</code>, or <code>discord</code>.</p><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h3><ol><li>Go to <strong>GitHub</strong> &gt; <strong>Settings</strong> &gt; <strong>Developer settings</strong> &gt; <strong>OAuth Apps</strong> &gt; <strong>New OAuth App</strong>.</li><li>Set <strong>Authorization callback URL</strong> to <code>https://your-domain/auth/social/github/callback</code>.</li><li>Copy the <strong>Client ID</strong> and generate a <strong>Client secret</strong>.</li></ol><p>Required scope: <code>user:email</code> (GateKeeper requests this automatically).</p><h3 id="google" tabindex="-1">Google <a class="header-anchor" href="#google" aria-label="Permalink to &quot;Google&quot;">​</a></h3><ol><li>Go to <a href="https://console.cloud.google.com/" target="_blank" rel="noreferrer">Google Cloud Console</a> &gt; <strong>APIs &amp; Services</strong> &gt; <strong>Credentials</strong> &gt; <strong>Create credentials</strong> &gt; <strong>OAuth client ID</strong>.</li><li>Choose <strong>Web application</strong>.</li><li>Add <code>https://your-domain/auth/social/google/callback</code> under <strong>Authorized redirect URIs</strong>.</li><li>Copy the <strong>Client ID</strong> and <strong>Client secret</strong>.</li></ol><p>Required scope: <code>openid email profile</code> (GateKeeper requests this automatically).</p><h3 id="discord" tabindex="-1">Discord <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Discord&quot;">​</a></h3><ol><li>Go to <a href="https://discord.com/developers/applications" target="_blank" rel="noreferrer">Discord Developer Portal</a> &gt; <strong>New Application</strong>.</li><li>Under <strong>OAuth2</strong>, add <code>https://your-domain/auth/social/discord/callback</code> as a redirect.</li><li>Copy the <strong>Client ID</strong> and <strong>Client secret</strong> from the OAuth2 page.</li></ol><p>Required scope: <code>identify email</code> (GateKeeper requests this automatically).</p><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><p>You can seed the provider credentials via environment variables. GateKeeper writes them to the settings database on first startup if the setting is not already set. The admin UI takes precedence after that.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>GITHUB_CLIENT_ID</code></td><td>GitHub OAuth App client ID</td></tr><tr><td><code>GITHUB_CLIENT_SECRET</code></td><td>GitHub OAuth App client secret</td></tr><tr><td><code>GOOGLE_CLIENT_ID</code></td><td>Google OAuth2 client ID</td></tr><tr><td><code>GOOGLE_CLIENT_SECRET</code></td><td>Google OAuth2 client secret</td></tr><tr><td><code>DISCORD_CLIENT_ID</code></td><td>Discord application client ID</td></tr><tr><td><code>DISCORD_CLIENT_SECRET</code></td><td>Discord application client secret</td></tr></tbody></table><p>Note: setting env vars does <strong>not</strong> enable the provider. You still need to check <strong>Enable</strong> in the Settings UI and save.</p><h2 id="linking-accounts" tabindex="-1">Linking accounts <a class="header-anchor" href="#linking-accounts" aria-label="Permalink to &quot;Linking accounts&quot;">​</a></h2><p>Users can connect or disconnect social providers from their profile page (<code>/</code>). The <strong>Connected accounts</strong> card shows all enabled providers and their link status.</p><p>A provider cannot be disconnected if it is the only login method and the account has no password set.</p><h2 id="registration-behavior" tabindex="-1">Registration behavior <a class="header-anchor" href="#registration-behavior" aria-label="Permalink to &quot;Registration behavior&quot;">​</a></h2><p>When a social login creates a new user, the <a href="/admin/registration.html">registration mode</a> setting applies:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th></tr></thead><tbody><tr><td><code>disabled</code> or <code>invite_only</code></td><td>Error - no account linked, contact admin</td></tr><tr><td><code>open</code></td><td>Account created automatically</td></tr><tr><td><code>approval</code></td><td>Account created in pending state, admin must approve</td></tr></tbody></table><p>Domain restrictions from <strong>Allowed domains for registration</strong> also apply.</p>',32)])])}const u=e(r,[["render",n]]);export{p as __pageData,u as default};
